};

function Extension() {
  const handlePick = async () =&gt; {
    const r = await fetch('shopify:admin/api/graphql.json', {
      method: 'POST',
      body: JSON.stringify({
        query: `query GetOrders($first: Int!) {
          orders(first: $first) {
            edges {
              node {
                id
                name
              }
            }
          }
        }`,
        variables: {first: 10},
      }),
    });

    const {data} = await r.json();

    await shopify.picker({
      heading: 'Select orders',
      items: data.orders.edges.map((edge) =&gt; ({
        id: edge.node.id,
        heading: edge.node.name,
      })),
    });
  };

  return (
    &lt;s-admin-block heading="Picker with GraphQL Data"&gt;
      &lt;s-button onClick={handlePick}&gt;Open Order Picker&lt;/s-button&gt;
    &lt;/s-admin-block&gt;
  );
}

import {render} from 'preact';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;

  const handleGenerate = async () =&gt; {
    const orderIds = data.selected.map((item) =&gt; item.id);

    const response = await fetch('/api/generate-packing-slip', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({orderIds}),
    });

    const {printUrl} = await response.json();
    return printUrl;
  };

  return (
    &lt;s-admin-print-action onPrint={handleGenerate}&gt;
      &lt;s-text&gt;Generating packing slip for {data.selected.length} orders&lt;/s-text&gt;
    &lt;/s-admin-print-action&gt;
  );
}

