import {render} from 'preact';
import {useState} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [additionalCount, setAdditionalCount] = useState(0);

  const handleSelectMore = async () =&gt; {
    const additionalProducts = await shopify.resourcePicker({
      type: 'product',
      multiple: 10,
      action: 'add',
    });

    if (additionalProducts) {
      setAdditionalCount(additionalProducts.length);
    }
  };

  const handleGenerate = async () =&gt; {
    const productIds = data.selected.map((item) =&gt; item.id);

    const response = await fetch('/api/generate-labels', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({productIds}),
    });

    const {printUrl} = await response.json();
    return printUrl;
  };

  return (
    &lt;s-admin-print-action onPrint={handleGenerate}&gt;
      &lt;s-text&gt;{data.selected.length} products selected&lt;/s-text&gt;
      &lt;s-button onClick={handleSelectMore}&gt;Add More Products&lt;/s-button&gt;
      {additionalCount &gt; 0 && &lt;s-text&gt;+{additionalCount} additional&lt;/s-text&gt;}
    &lt;/s-admin-print-action&gt;
  );
}

import {render} from 'preact';
import {useState, useEffect} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [orders, setOrders] = useState([]);

  useEffect(() =&gt; {
    const fetchOrders = async () =&gt; {
      const orderIds = data.selected.map((item) =&gt; item.id);

      const {data: ordersData} = await shopify.query(
        `query GetOrders($ids: [ID!]!) {
          nodes(ids: $ids) {
            ... on Order {
              id
              name
              shippingAddress {
                address1
                city
                country
              }
            }
          }
        }`,
        {variables: {ids: orderIds}},
      );

      setOrders(ordersData.nodes);
    };

    fetchOrders();
  }, [data]);

  const handleGenerate = async () =&gt; {
    const response = await fetch('/api/generate-shipping-manifest', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({orders}),
    });

    const {printUrl} = await response.json();
    return printUrl;
  };

  return (
    &lt;s-admin-print-action onPrint={handleGenerate}&gt;
      &lt;s-text&gt;Shipping manifest for {orders.length} orders&lt;/s-text&gt;
      {orders.map((order) =&gt; (
        &lt;s-text key={order.id}&gt;{order.name}&lt;/s-text&gt;
      ))}
    &lt;/s-admin-print-action&gt;
  );
}

import {render} from 'preact';
import {useState} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [selected, setSelected] = useState([]);

  const parentProductId = data.selected[0]?.id;

  const handleSelectComponents = async () =&gt; {
    const componentProducts = await shopify.resourcePicker({
      type: 'product',
      multiple: 5,
      action: 'select',
      filter: {
        draft: false,
        archived: false,
      },
    });

    if (componentProducts) {
      setSelected(componentProducts);

      await fetch('/api/bundles/configure', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
          bundleProductId: parentProductId,
          components: componentProducts.map((p) =&gt; ({
            productId: p.id,
            quantity: 1,
          })),
        }),
      });
    }
  };

  return (
    &lt;s-admin-block heading="Bundle Configuration"&gt;
      &lt;s-button onClick={handleSelectComponents}&gt;Select Components&lt;/s-button&gt;
      {selected.length &gt; 0 && (
        &lt;s-text&gt;{selected.length} components selected&lt;/s-text&gt;
      )}
    &lt;/s-admin-block&gt;
  );
}

