import {render} from 'preact';
import {useState, useEffect} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [components, setComponents] = useState([]);

  useEffect(() =&gt; {
    const loadConfig = async () =&gt; {
      const productId = data.selected[0]?.id;

      const {data: bundleData} = await shopify.query(
        `query GetBundleComponents($id: ID!) {
          product(id: $id) {
            id
            title
            metafield(namespace: "bundle", key: "components") {
              value
            }
          }
        }`,
        {variables: {id: productId}},
      );

      const comps = bundleData.product.metafield
        ? JSON.parse(bundleData.product.metafield.value)
        : [];

      setComponents(comps);
    };

    loadConfig();
  }, [data]);

  return (
    &lt;s-admin-block heading="Current Bundle"&gt;
      &lt;s-text&gt;{components.length} components configured&lt;/s-text&gt;
      {components.map((comp, i) =&gt; (
        &lt;s-text key={i}&gt;Component {i + 1}&lt;/s-text&gt;
      ))}
    &lt;/s-admin-block&gt;
  );
}

import {render} from 'preact';
import {useState} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const [created, setCreated] = useState(null);

  const handleCreate = async () =&gt; {
    const activity = await shopify.intents.invoke('create:shopify/Product');
    const response = await activity.complete;

    if (response.code === 'ok') {
      const newProductId = response.data?.product?.id;
      setCreated(newProductId);
    }
  };

  return (
    &lt;s-admin-block heading="Add Component"&gt;
      &lt;s-button onClick={handleCreate}&gt;Create New Component Product&lt;/s-button&gt;
      {created && &lt;s-text&gt;Component created: {created}&lt;/s-text&gt;}
    &lt;/s-admin-block&gt;
  );
}

import {render} from 'preact';
import {useState} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [selected, setSelected] = useState([]);

  const parentVariantId = data.selected[0]?.id;

  const handleSelectComponents = async () =&gt; {
    const componentVariants = await shopify.resourcePicker({
      type: 'variant',
      multiple: 5,
      action: 'select',
      filter: {
        draft: false,
        archived: false,
      },
    });

    if (componentVariants) {
      setSelected(componentVariants);

      await fetch('/api/bundles/configure-variant', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
          bundleVariantId: parentVariantId,
          componentVariants: componentVariants.map((v) =&gt; ({
            variantId: v.id,
            quantity: 1,
          })),
        }),
      });
    }
  };

  return (
    &lt;s-admin-block heading="Variant Bundle Configuration"&gt;
      &lt;s-button onClick={handleSelectComponents}&gt;Select Variant Components&lt;/s-button&gt;
      {selected.length &gt; 0 && (
        &lt;s-text&gt;{selected.length} variant components selected&lt;/s-text&gt;
      )}
    &lt;/s-admin-block&gt;
  );
}

