import {render} from 'preact';
import {useState, useEffect} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [created, setCreated] = useState(null);
  const [productId, setProductId] = useState(null);

  useEffect(() =&gt; {
    const getParentProduct = async () =&gt; {
      const variantId = data.selected[0]?.id;

      const {data: parentData} = await shopify.query(
        `query GetParentProduct($id: ID!) {
          productVariant(id: $id) {
            product {
              id
            }
          }
        }`,
        {variables: {id: variantId}},
      );

      setProductId(parentData.productVariant.product.id);
    };

    getParentProduct();
  }, [data]);

  const handleCreate = async () =&gt; {
    const activity = await shopify.intents.invoke('create:shopify/ProductVariant', {
      data: {productId},
    });

    const response = await activity.complete;

    if (response.code === 'ok') {
      setCreated(true);
    }
  };

  return (
    &lt;s-admin-block heading="Add Variant Component"&gt;
      {productId && (
        &lt;&gt;
          &lt;s-button onClick={handleCreate}&gt;Create Component Variant&lt;/s-button&gt;
          {created && &lt;s-banner status="success"&gt;Component variant created&lt;/s-banner&gt;}
        &lt;/&gt;
      )}
    &lt;/s-admin-block&gt;
  );
}

import {render} from 'preact';
import {useState, useEffect} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [components, setComponents] = useState([]);
  const [variantInfo, setVariantInfo] = useState(null);

  useEffect(() =&gt; {
    const loadConfig = async () =&gt; {
      const variantId = data.selected[0]?.id;

      const {data: variantData} = await shopify.query(
        `query GetVariantBundleComponents($id: ID!) {
          productVariant(id: $id) {
            id
            displayName
            sku
            metafield(namespace: "bundle", key: "variant_components") {
              value
            }
          }
        }`,
        {variables: {id: variantId}},
      );

      setVariantInfo(variantData.productVariant);

      const comps = variantData.productVariant.metafield
        ? JSON.parse(variantData.productVariant.metafield.value)
        : [];

      setComponents(comps);
    };

    loadConfig();
  }, [data]);

  return (
    &lt;s-admin-block heading="Variant Bundle"&gt;
      {variantInfo && (
        &lt;&gt;
          &lt;s-text&gt;{variantInfo.displayName}&lt;/s-text&gt;
          &lt;s-text&gt;SKU: {variantInfo.sku}&lt;/s-text&gt;
          &lt;s-text&gt;{components.length} variant components configured&lt;/s-text&gt;
        &lt;/&gt;
      )}
    &lt;/s-admin-block&gt;
  );
}

import {render} from 'preact';
import {useState} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [updated, setUpdated] = useState(false);

  const {id: productId, sellingPlanId} = data.selected[0];

  const handleUpdate = async () =&gt; {
    if (!sellingPlanId) {
      console.error('No selling plan selected');
      shopify.close();
      return;
    }

    const response = await fetch('/api/subscriptions/update', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        productId,
        sellingPlanId,
        action: 'modify',
      }),
    });

    if (response.ok) {
      setUpdated(true);
      setTimeout(() =&gt; shopify.close(), 1500);
    }
  };

  return (
    &lt;s-admin-action title="Manage Subscription"&gt;
      &lt;s-text&gt;Product: {productId}&lt;/s-text&gt;
      &lt;s-text&gt;Selling Plan: {sellingPlanId}&lt;/s-text&gt;
      &lt;s-button onClick={handleUpdate}&gt;Update Subscription&lt;/s-button&gt;
      {updated && &lt;s-banner status="success"&gt;Subscription updated!&lt;/s-banner&gt;}
    &lt;/s-admin-action&gt;
  );
}

