import {render} from 'preact';
import {useState} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [confirming, setConfirming] = useState(false);
  const [removed, setRemoved] = useState(false);

  const {id: productId, sellingPlanId} = data.selected[0];

  const handleRemove = async () =&gt; {
    setConfirming(false);

    await fetch('/api/selling-plans/remove-product', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({productId, sellingPlanId}),
    });

    setRemoved(true);
    setTimeout(() =&gt; shopify.close(), 1500);
  };

  return (
    &lt;s-admin-action title="Remove from Selling Plan"&gt;
      {!confirming ? (
        &lt;s-button onClick={() =&gt; setConfirming(true)}&gt;
          Remove Product
        &lt;/s-button&gt;
      ) : (
        &lt;&gt;
          &lt;s-text&gt;Are you sure you want to remove this product?&lt;/s-text&gt;
          &lt;s-button onClick={handleRemove}&gt;Confirm Remove&lt;/s-button&gt;
          &lt;s-button onClick={() =&gt; setConfirming(false)}&gt;Cancel&lt;/s-button&gt;
        &lt;/&gt;
      )}
      {removed && &lt;s-banner status="success"&gt;Product removed from plan&lt;/s-banner&gt;}
    &lt;/s-admin-action&gt;
  );
}

import {render} from 'preact';
import {useState} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {data} = shopify;
  const [plan, setPlan] = useState(null);

  const {sellingPlanId} = data.selected[0];

  const handleValidate = async () =&gt; {
    const {data: planData} = await shopify.query(
      `query GetSellingPlan($id: ID!) {
        sellingPlanGroup(id: $id) {
          sellingPlans(first: 1) {
            edges {
              node {
                id
                name
                options
              }
            }
          }
        }
      }`,
      {variables: {id: sellingPlanId}},
    );

    setPlan(planData.sellingPlanGroup.sellingPlans.edges[0]?.node);
    setTimeout(() =&gt; shopify.close(), 2000);
  };

  return (
    &lt;s-admin-action title="Validate Selling Plan"&gt;
      &lt;s-button onClick={handleValidate}&gt;Check Plan Details&lt;/s-button&gt;
      {plan && (
        &lt;&gt;
          &lt;s-text&gt;Plan: {plan.name}&lt;/s-text&gt;
          &lt;s-text&gt;Options: {plan.options.length}&lt;/s-text&gt;
        &lt;/&gt;
      )}
    &lt;/s-admin-action&gt;
  );
}

