import {render} from 'preact';
import {useState} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const [products, setProducts] = useState([]);
  const [updated, setUpdated] = useState(false);

  const handleQuery = async () =&gt; {
    const {data: productsData} = await shopify.query(
      `query GetProducts {
        products(first: 10) {
          edges {
            node {
              id
              title
              totalInventory
            }
          }
        }
      }`,
    );

    setProducts(productsData.products.edges);
  };

  const handleUpdate = async () =&gt; {
    const productId = products[0]?.node.id;

    if (!productId) return;

    const {data: updateData} = await shopify.query(
      `mutation UpdateProduct($id: ID!, $input: ProductInput!) {
        productUpdate(id: $id, product: $input) {
          product {
            id
            tags
          }
          userErrors {
            field
            message
          }
        }
      }`,
      {
        variables: {
          id: productId,
          input: {tags: ['processed', 'reviewed']},
        },
      },
    );

    if (updateData.productUpdate.product) {
      setUpdated(true);
    }
  };

  return (
    &lt;s-admin-block heading="GraphQL Operations"&gt;
      &lt;s-stack direction="block"&gt;
        &lt;s-button onClick={handleQuery}&gt;Query Products&lt;/s-button&gt;
        {products.length &gt; 0 && (
          &lt;&gt;
            &lt;s-text&gt;{products.length} products found&lt;/s-text&gt;
            &lt;s-button onClick={handleUpdate}&gt;Update First Product&lt;/s-button&gt;
          &lt;/&gt;
        )}
        {updated && &lt;s-text&gt;Product tags updated!&lt;/s-text&gt;}
      &lt;/s-stack&gt;
    &lt;/s-admin-block&gt;
  );
}

import {render} from 'preact';
import {useState, useEffect} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const [preferences, setPreferences] = useState(null);

  useEffect(() =&gt; {
    const loadPreferences = async () =&gt; {
      const prefs = await shopify.storage.get('userPreferences');
      setPreferences(prefs);
    };

    loadPreferences();
  }, []);

  const handleSave = async () =&gt; {
    await shopify.storage.set('userPreferences', {
      theme: 'dark',
      notifications: true,
      defaultView: 'grid',
    });

    const updated = await shopify.storage.get('userPreferences');
    setPreferences(updated);
  };

  return (
    &lt;s-admin-block heading="User Preferences"&gt;
      &lt;s-button onClick={handleSave}&gt;Save Preferences&lt;/s-button&gt;
      {preferences && (
        &lt;s-stack direction="block"&gt;
          &lt;s-text&gt;Theme: {preferences.theme}&lt;/s-text&gt;
          &lt;s-text&gt;Notifications: {String(preferences.notifications)}&lt;/s-text&gt;
          &lt;s-text&gt;View: {preferences.defaultView}&lt;/s-text&gt;
        &lt;/s-stack&gt;
      )}
    &lt;/s-admin-block&gt;
  );
}

